/**
 * Localize an expected-duration string like "2-3 mins" (seeded DB values are
 * English). Unknown formats pass through untouched.
 */
export function formatDuration(duration: string | null | undefined, lang: string): string {
  if (!duration) return '';
  const m = duration.match(/^(\d+)\s*-\s*(\d+)\s*mins?$/i);
  if (!m) return duration;
  const unit = lang === 'fa' ? 'دقیقه' : lang === 'ps' ? 'دقيقې' : 'mins';
  return `${m[1]}-${m[2]} ${unit}`;
}

export function translate(code: string, key: string, params?: Record<string, string | number>): string {
  let str = translations[code]?.[key] || translations.en[key] || key;
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      str = str.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
    }
  }
  return str;
}
